'use strict';
// Reports: sales (orders, tax, invoiced, shipping, refunds, coupons), products (bestsellers,
// ordered, views, low stock), customers (order total, order count, new accounts), reviews
// (by customers, by products), marketing (search terms, products in cart, abandoned carts),
// Refresh Statistics.
//
// Report pages are generated by the kit background job 'admin.report': "Show Report" (GET
// with the filter params) creates a run in temp.admin_report_runs and enqueues the job; the
// page polls until the run is done, then shows the rows from temp.admin_report_rows. A run
// is reused while its parameters and the underlying data (signature) are unchanged.
const R = require('../lib/reports');

module.exports = (r, ctx) => {
  const { kit, U, grid, view } = ctx;
  const h = kit.escapeHtml;
  const statusOptions = () => kit.sql('SELECT status, label FROM order_statuses ORDER BY label').all().map((s) => [s.status, s.label]);
  const cell = (c, v, period) => {
    if (c.type === 'period') return h(R.periodLabel(v, period));
    if (c.type === 'money') return U.money(v || 0);
    if (c.type === 'num') return U.num(v || 0);
    if (c.type === 'pct') return v == null ? '' : `${Number(v).toFixed(2)}%`;
    if (c.type === 'datetime') return h(U.date.datetime(v));
    return c.key === 'name' || c.key === 'product_name' ? U.htmlName(v ?? '') : h(v ?? '');
  };

  function reportPage(def) {
    return async (req, reply) => {
      const db = kit.db();
      U.ensureSqlFunctions(db);
      const q = req.query || {};
      const p = R.params(q, { statuses: def.filter === 'sales' });
      const submitted = def.filter === 'none' || q.report_from != null || q.report_to != null || q.filter === '1';
      const m = {
        title: def.title, def, p, q, statuses: statusOptions(), crumbs: [['Reports', null], [def.crumb[0], null], [def.crumb[1], null]],
        fromValue: p.from ? U.shortDate(p.from) : U.str(q.report_from), toValue: p.to ? U.shortDate(p.to) : U.str(q.report_to),
        state: 'form', rows: [], totals: null, run: null, cell, errors: {},
      };
      if (submitted) {
        if (def.filter !== 'none') {
          if (!p.from) m.errors.report_from = U.str(q.report_from) ? 'Please enter a valid date (M/D/YY).' : 'This is a required field.';
          if (!p.to) m.errors.report_to = U.str(q.report_to) ? 'Please enter a valid date (M/D/YY).' : 'This is a required field.';
          if (p.from && p.to && p.from > p.to) m.errors.report_to = 'The To date must be on or after the From date.';
        }
        if (!Object.keys(m.errors).length) {
          const params = def.filter === 'none' ? '{}' : JSON.stringify(p);
          const sig = R.dataSig(db, def.type);
          let run = kit.sql('SELECT * FROM temp.admin_report_runs WHERE type = ? AND params = ? AND sig = ? ORDER BY id DESC LIMIT 1').get(def.type, params, sig);
          if (run && run.status !== 'done') {
            const job = kit.sql('SELECT status, error FROM temp.kit_jobs WHERE id = ?').get(run.job_id);
            if (job && job.status === 'failed') { m.state = 'failed'; m.error = String(job.error || '').split('\n')[0]; kit.sql('DELETE FROM temp.admin_report_runs WHERE id = ?').run(run.id); run = null; }
          }
          if (!run && m.state !== 'failed') {
            const id = Number(kit.sql("INSERT INTO temp.admin_report_runs (type, params, sig, status, created_at) VALUES (?, ?, ?, 'queued', ?)").run(def.type, params, sig, kit.nowSql()).lastInsertRowid);
            // admin_job widget slot (../../widgets.js): a slow job, 10-60 s of site time per report/params
            const slow = kit.widget('admin_job') === 'slow';
            const jid = kit.jobs.enqueue('admin.report', { run_id: id }, slow ? { delay: kit.widgets.jobSeconds(`${def.type}:${params}`) } : undefined);
            kit.sql('UPDATE temp.admin_report_runs SET job_id = ? WHERE id = ?').run(jid, id);
            run = kit.sql('SELECT * FROM temp.admin_report_runs WHERE id = ?').get(id);
          }
          m.run = run;
          if (run) kit.sql('UPDATE temp.admin_report_runs SET last_shown = (SELECT coalesce(max(last_shown), 0) + 1 FROM temp.admin_report_runs) WHERE id = ?').run(run.id);
          if (run && run.status === 'done') {
            m.state = 'done';
            m.totals = JSON.parse(run.totals || '{}');
            if (def.paged) {
              const sortKey = def.columns.find((c) => q.sort && q.sort.startsWith(c.key + '_'));
              const dir = /_desc$/.test(q.sort || '') ? 'DESC' : 'ASC';
              m.pager = kit.paginate(req, run.row_count, { perPage: 20, maxPerPage: 200 });
              const order = sortKey ? `json_extract(data, '$.${sortKey.key}') ${dir}, n` : 'n';
              m.rows = kit.sql(`SELECT data FROM temp.admin_report_rows WHERE run_id = ? ORDER BY ${order} LIMIT ? OFFSET ?`).pluck().all(run.id, m.pager.limit, m.pager.offset).map((x) => JSON.parse(x));
              m.sortHref = (k) => kit.urlWith(req, { sort: `${k}_${q.sort === `${k}_asc` ? 'desc' : 'asc'}`, page: null });
            } else m.rows = kit.sql('SELECT data FROM temp.admin_report_rows WHERE run_id = ? ORDER BY n').pluck().all(run.id).map((x) => JSON.parse(x));
          } else if (run) m.state = 'pending';
        }
      }
      if (m.state === 'pending' && kit.widget('admin_job')) m.jobPoll = `/admin/reports/job/${m.run.id}/`;
      return view(reply, 'report', m);
    };
  }
  // admin_job widget slot: the report page polls its run (404 while the slot is off)
  r.get('/reports/job/:id', async (req) => {
    kit.widgets.need('admin_job');
    const run = kit.sql('SELECT r.status, j.status AS job FROM temp.admin_report_runs r LEFT JOIN temp.kit_jobs j ON j.id = r.job_id WHERE r.id = ?').get(+req.params.id);
    if (!run) throw kit.httpError(404, 'No such report run.');
    return { status: run.job === 'failed' ? 'failed' : run.status };
  });
  for (const def of Object.values(R.REPORTS)) {
    const rel = def.path.replace(/^\/admin/, '').replace(/\/$/, '');
    r.get(rel, reportPage(def));
    r.get(`${rel}/index`, reportPage(def));
  }
  // Magento's old-style filter URLs (/filter/<base64 of the query>/) still resolve
  for (const def of Object.values(R.REPORTS)) {
    r.get(`${def.path.replace(/^\/admin/, '').replace(/\/$/, '')}/filter/:f`, async (req, reply) => {
      let qs = '';
      try { qs = Buffer.from(decodeURIComponent(req.params.f), 'base64').toString('utf8'); } catch {}
      return reply.redirect(`${def.path}?${new URLSearchParams(qs).toString()}`);
    });
  }

  // ---------------------------------------------------------------- low stock (grid)
  const LOW = {
    id: 'lowstock_grid', url: '/admin/reports/report_product/lowstock/', idCol: 'g.id', from: 'temp.admin_pgrid g',
    where: "g.type IN ('simple', 'virtual', 'downloadable') AND coalesce(g.qty, 0) < coalesce(g.notify_stock_qty, 1)", defaultSort: 'qty_asc',
    columns: [
      { key: 'name', label: 'Product', sql: '(SELECT name FROM products p WHERE p.id = g.id)', sort: false, filter: { type: 'text', build: (v) => ({ where: "g.id IN (SELECT id FROM products WHERE name LIKE ? ESCAPE '\\')", params: [`%${v.replace(/[\\%_]/g, '\\$&')}%`] }) }, html: (x) => `<a href="/admin/catalog/product/edit/id/${x._id}/">${U.htmlName(x.name)}</a>` },
      { key: 'sku', label: 'SKU', sql: '(SELECT sku FROM products p WHERE p.id = g.id)', sort: false, filter: { type: 'text', build: (v) => ({ where: "g.id IN (SELECT id FROM products WHERE sku LIKE ? ESCAPE '\\')", params: [`%${v.replace(/[\\%_]/g, '\\$&')}%`] }) } },
      { key: 'qty', label: 'Quantity', sql: 'g.qty', cls: 'num', filter: { type: 'range' }, html: (x) => U.num(x.qty) },
    ],
  };
  r.get('/reports/report_product/lowstock', async (req, reply) => view(reply, 'grid_page', { title: 'Low Stock Report', g: grid.build(req, kit, LOW), crumbs: [['Reports', null], ['Products', null], ['Low Stock', null]] }));

  // ---------------------------------------------------------------- search terms report
  const TERMS = {
    id: 'search_report_grid', url: '/admin/search/term/report/', idCol: 't.id', from: 'search_terms t', defaultSort: 'popularity_desc',
    columns: [
      { key: 'query_text', label: 'Search Query', sql: 't.query_text', filter: { type: 'text' } },
      { key: 'num_results', label: 'Results', sql: 't.num_results', cls: 'num', filter: { type: 'range' } },
      { key: 'popularity', label: 'Hits', sql: 't.popularity', cls: 'num', filter: { type: 'range' } },
    ],
  };
  r.get('/search/term/report', async (req, reply) => view(reply, 'grid_page', { title: 'Search Terms Report', g: grid.build(req, kit, TERMS), crumbs: [['Reports', null], ['Marketing', null], ['Search Terms', null]] }));
  r.get('/reports/report_search', async (req, reply) => reply.redirect('/admin/search/term/report/'));

  // ---------------------------------------------------------------- shopping carts
  const INCART = {
    id: 'shopcart_product_grid', url: '/admin/reports/report_shopcart/product/', idCol: 'x.product_id',
    from: "(SELECT ci.product_id, max(ci.name) AS name, max(ci.price) AS price, count(DISTINCT ci.cart_id) AS carts FROM cart_items ci JOIN carts c ON c.id = ci.cart_id WHERE c.is_active = 1 AND ci.parent_item_id IS NULL GROUP BY ci.product_id) x",
    defaultSort: 'carts_desc',
    columns: [
      { key: 'product_id', label: 'ID', sql: 'x.product_id', cls: 'num' },
      { key: 'name', label: 'Product', sql: 'x.name', filter: { type: 'text' }, html: (x) => `<a href="/admin/catalog/product/edit/id/${x._id}/">${U.htmlName(x.name)}</a>` },
      { key: 'price', label: 'Price', sql: 'x.price', cls: 'num', html: (x) => U.money(x.price) },
      { key: 'carts', label: 'Carts', sql: 'x.carts', cls: 'num' },
      { key: 'orders', label: 'Orders', sql: '(SELECT count(DISTINCT order_id) FROM order_items oi WHERE oi.product_id = x.product_id)', cls: 'num' },
    ],
  };
  r.get('/reports/report_shopcart/product', async (req, reply) => view(reply, 'grid_page', { title: 'Products in Carts', g: grid.build(req, kit, INCART), crumbs: [['Reports', null], ['Marketing', null], ['Products in Cart', null]] }));
  const ABANDONED = {
    id: 'shopcart_abandoned_grid', url: '/admin/reports/report_shopcart/abandoned/', idCol: 'c.id', from: 'carts c', where: 'c.is_active = 1 AND coalesce(c.items_count, 0) > 0', defaultSort: 'updated_at_desc',
    columns: [
      { key: 'customer', label: 'Customer', sql: "(SELECT trim(coalesce(firstname, '') || ' ' || coalesce(lastname, '')) FROM customers cu WHERE cu.id = c.customer_id)", filter: { type: 'text' }, html: (x) => (x.customer_id ? `<a href="/admin/customer/index/edit/id/${x.customer_id}/active_tab/cart/">${h(x.customer)}</a>` : 'Guest') },
      { key: 'customer_id', label: 'cid', sql: 'c.customer_id', hidden: true, needed: true },
      { key: 'email', label: 'Email', sql: '(SELECT email FROM customers cu WHERE cu.id = c.customer_id)', filter: { type: 'text' } },
      { key: 'items_count', label: 'Products', sql: 'c.items_count', cls: 'num' },
      { key: 'items_qty', label: 'Quantity', sql: 'c.items_qty', cls: 'num', html: (x) => U.num(x.items_qty) },
      { key: 'subtotal', label: 'Subtotal', sql: 'c.subtotal', cls: 'num', html: (x) => U.money(x.subtotal) },
      { key: 'coupon_code', label: 'Applied Coupon', sql: 'c.coupon_code' },
      { key: 'created_at', label: 'Created', sql: 'c.created_at', filter: { type: 'daterange' }, html: (x) => h(U.date.datetime(x.created_at)) },
      { key: 'updated_at', label: 'Updated', sql: 'c.updated_at', filter: { type: 'daterange' }, html: (x) => h(U.date.datetime(x.updated_at)) },
    ],
  };
  r.get('/reports/report_shopcart/abandoned', async (req, reply) => view(reply, 'grid_page', { title: 'Abandoned Carts', g: grid.build(req, kit, ABANDONED), crumbs: [['Reports', null], ['Marketing', null], ['Abandoned Carts', null]] }));

  // ---------------------------------------------------------------- refresh statistics
  const STAT = require('../jobs').STAT_CODES;
  r.get('/reports/report_statistics', async (req, reply) => {
    const jobs = kit.sql("SELECT id, status, run_at, done_at, payload FROM temp.kit_jobs WHERE type = 'admin.statistics.refresh' ORDER BY id DESC LIMIT 5").all();
    const pending = jobs.some((j) => j.status === 'queued');
    const rows = Object.entries(STAT).map(([code, name]) => ({ code, name, updated: kit.sql('SELECT value FROM store_config WHERE path = ?').pluck().get(`reports/statistics/${code}/updated_at`) }));
    const html = `
      ${pending ? '<div class="message message-notice notice" data-report-wait="1500"><div>Statistics are being refreshed in the background. This page reloads automatically.</div></div>' : ''}
      <form method="post" action="/admin/reports/report_statistics/refresh/" id="statistics_form">${req.csrfToken ? `<input type="hidden" name="_csrf" value="${h(req.csrfToken())}">` : ''}
      <div class="grid-toolbar"><div class="left mass-actions"><label for="stat_action">Actions</label><select id="stat_action" name="mode"><option value="recent">Refresh Statistics for the Last Day</option><option value="lifetime">Refresh Lifetime Statistics</option></select><button type="submit" class="action-secondary">Submit</button></div></div>
      <table class="data-grid" id="gridReport"><thead><tr><th class="data-grid-checkbox-cell"><span class="sr-only">Select</span></th><th>Report</th><th>Updated</th></tr></thead><tbody>
      ${rows.map((x) => `<tr><td class="data-grid-checkbox-cell"><input type="checkbox" name="codes" value="${x.code}" aria-label="Select ${h(x.name)}" checked></td><td>${h(x.name)}</td><td>${x.updated ? h(U.date.datetime(x.updated)) : 'Never'}</td></tr>`).join('')}
      </tbody></table></form>
      <p class="muted">Report pages are generated live from the order data; refreshing statistics rebuilds the aggregate tables (report_sales, report_bestsellers, ...).</p>`;
    return view(reply, 'message_page', { title: 'Refresh Statistics', html, crumbs: [['Reports', null], ['Statistics', null], ['Refresh Statistics', null]] });
  });
  r.post('/reports/report_statistics/refresh', async (req, reply) => {
    const codes = U.arr(req.body.codes).filter((c) => STAT[c]);
    const mode = U.str(req.body.mode) === 'lifetime' ? 'lifetime' : 'recent';
    if (!codes.length) { req.flash('error', 'Please select a report.'); return reply.redirect('/admin/reports/report_statistics/'); }
    kit.jobs.enqueue('admin.statistics.refresh', { codes, mode });
    req.flash('success', mode === 'lifetime' ? 'We updated lifetime statistic.' : 'Recent statistics have been updated.');
    return reply.redirect('/admin/reports/report_statistics/');
  });
  for (const [p, mode] of [['/reports/report_statistics/refreshLifetime', 'lifetime'], ['/reports/report_statistics/refreshRecent', 'recent']]) {
    r.post(p, async (req, reply) => {
      const codes = U.arr(req.body.codes).filter((c) => STAT[c]);
      kit.jobs.enqueue('admin.statistics.refresh', { codes: codes.length ? codes : Object.keys(STAT), mode });
      req.flash('success', mode === 'lifetime' ? 'We updated lifetime statistic.' : 'Recent statistics have been updated.');
      return reply.redirect('/admin/reports/report_statistics/');
    });
  }
};
